<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api/admin';const rows=ref<any[]>([]),customers=ref<any[]>([]),loading=ref(false),visible=ref(false),editing=ref<any>();const filters=reactive({keyword:'',status:'',customerId:null});const empty=()=>({customerId:null,customerName:'',contactPhone:'',planCode:'',planName:'',planType:'',monthlyFee:0,contractPeriod:'',umallOrderNo:'',serviceNumber:'',activationStatus:'',contractStatus:'',orderSource:'ADMIN',status:'待处理',reconciliationStatus:'待对账'});const form=reactive<any>(empty());async function load(){loading.value=true;try{[rows.value,customers.value]=await Promise.all([api.orders(filters),api.customers()]) as any}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}function open(row?:any){editing.value=row;Object.assign(form,empty(),row||{});visible.value=true}function customerChanged(id:number){const c=customers.value.find(x=>x.id===id);if(c){form.customerName=c.name;form.contactPhone=c.phone}}async function save(){try{editing.value?await api.updateOrder(editing.value.id,form):await api.createOrder(form);ElMessage.success('订单已保存');visible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>订单管理</h1><p>管理内部订单与 UMALL 正式订单的外围关联信息。</p></div><el-button type="primary" @click="open()">新增订单</el-button></div><div class="filter-bar"><el-input v-model="filters.keyword" placeholder="订单号 / 手机号" clearable/><el-input v-model="filters.status" placeholder="办理状态" clearable/><el-select v-model="filters.customerId" placeholder="客户" clearable filterable><el-option v-for="c in customers" :key="c.id" :label="`${c.name||'未命名'} · ${c.phone}`" :value="c.id"/></el-select><el-button @click="load">查询</el-button></div><div class="table-card"><div class="table-toolbar"><span class="table-title">业务订单</span><span class="table-meta">共 {{rows.length}} 条</span></div><el-table :data="rows" v-loading="loading"><el-table-column prop="orderNo" label="内部订单号" min-width="185"/><el-table-column prop="umallOrderNo" label="UMALL订单号" min-width="160"/><el-table-column prop="customerName" label="客户" min-width="100"/><el-table-column prop="contactPhone" label="手机号" min-width="130"/><el-table-column prop="planName" label="套餐" min-width="180"/><el-table-column label="月费" width="90"><template #default="s">HK${{Number(s.row.monthlyFee||0).toFixed(2)}}</template></el-table-column><el-table-column prop="serviceNumber" label="服务号码" min-width="130"/><el-table-column prop="status" label="办理状态" width="110"/><el-table-column prop="activationStatus" label="激活" width="100"/><el-table-column prop="contractStatus" label="合约" width="100"/><el-table-column prop="reconciliationStatus" label="对账" width="100"/><el-table-column label="操作" fixed="right" width="90"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" :title="editing?'编辑订单':'新增订单'" width="780"><div class="hint-box" style="margin-bottom:18px">这里只记录外围业务信息，不上传身份证件、地址证明或 UMALL 正式身份资料。</div><el-form label-position="top"><el-row :gutter="18"><el-col :span="12"><el-form-item label="客户"><el-select v-model="form.customerId" filterable style="width:100%" @change="customerChanged"><el-option v-for="c in customers" :key="c.id" :label="`${c.name||'未命名'} · ${c.phone}`" :value="c.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="联系电话"><el-input v-model="form.contactPhone"/></el-form-item></el-col><el-col :span="12"><el-form-item label="套餐编码"><el-input v-model="form.planCode"/></el-form-item></el-col><el-col :span="12"><el-form-item label="套餐名称"><el-input v-model="form.planName"/></el-form-item></el-col><el-col :span="8"><el-form-item label="月费"><el-input-number v-model="form.monthlyFee" :precision="2" :min="0" style="width:100%"/></el-form-item></el-col><el-col :span="8"><el-form-item label="合约期"><el-input v-model="form.contractPeriod" placeholder="例如 24个月"/></el-form-item></el-col><el-col :span="8"><el-form-item label="办理状态"><el-input v-model="form.status"/></el-form-item></el-col><el-col :span="12"><el-form-item label="UMALL订单号"><el-input v-model="form.umallOrderNo"/></el-form-item></el-col><el-col :span="12"><el-form-item label="服务号码"><el-input v-model="form.serviceNumber"/></el-form-item></el-col><el-col :span="8"><el-form-item label="激活状态"><el-input v-model="form.activationStatus"/></el-form-item></el-col><el-col :span="8"><el-form-item label="合约状态"><el-input v-model="form.contractStatus"/></el-form-item></el-col><el-col :span="8"><el-form-item label="对账状态"><el-input v-model="form.reconciliationStatus"/></el-form-item></el-col></el-row></el-form><template #footer><div class="dialog-footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></div></template></el-dialog></div></template>

